""" Return the CPU loading for all the processors between last and ref measures.
    The average on all processors is inserted in front of the list. """
def cpu_statistics(last: Any, ref: Any) -> object {
    cpu = [];
    for unit in zip(last, ref) {
        work = unit[0][0] - unit[1][0];
        idle = unit[0][1] - unit[1][1];
        total = work + idle;
        cpu.append(((100.0 * work) / total) if total else 0);
    }
    return cpu;
}

""" convert RGB to YUV color
    :param Y: Y value (0;1)
    :param Db: Db value (-1.333-1.333)
    :param Dr: Dr value (-1.333-1.333)
    :return: YUV (PAL) tuple (Y0;1 U-0.436-0.436 V-0.615-0.615) """
def YDbDrtoYUV(Y: Any, Db: Any, Dr: Any) -> object {
    U = Db / 3.059;
    V = Dr / -2.169;
    return (Y, U, V);
}

"""Calculate volume at time t given envelope env

    envelope is a list of [time, volume] points
    time is measured in samples
    envelope should be sorted by time

    """
def calc_vol(t: Any, env: Any) -> object {
    if (len(env) == 0) {
        return 1.0;
    }
    if (len(env) == 1) {
        return env[0][1];
    }
    n = 0;
    while ((n < len(env)) and (env[n][0] < t)) {
        n += 1;
    }
    if (n == 0) {
        return env[0][1];
    }
    if (n == len(env)) {
        return env[-1][1];
    }
    f = float((t - env[(n - 1)][0])) / (env[n][0] - env[(n - 1)][0]);
    return ((env[(n - 1)][1] * (1.0 - f)) + (env[n][1] * f));
}

"""Merge dicts whose values are int.

    if key is present in multiple dict, choose the max.

    Args:
        dicts (list): list of dicts to merge

    Retrun:
        (dict) merged dict
    """
def max_dict(dicts: Any) -> object {
    ret = {};
    for cur_dict in dicts {
        for (key, value) in cur_dict.items() {
            ret[key] = max(d.get(key, 0) for d in dicts);
        }
    }
    return ret;
}

